// get_id_asesor — elige asesor por nombre, respetando las exclusiones configuradas

function toMinutes(hhmm) {
  if (hhmm === null || hhmm === undefined) return null;
  const m = String(hhmm).match(/(\d{1,2}):(\d{2})/);
  return m ? parseInt(m[1], 10) * 60 + parseInt(m[2], 10) : null;
}
function toHHMM(mins) {
  return String(Math.floor(mins / 60)).padStart(2, '0') + ':' + String(mins % 60).padStart(2, '0');
}
function normU(s) {
  return String(s ?? '').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, ' ').trim();
}
function normL(s) { return normU(s).toLowerCase(); }
// Todas las palabras del patrón tienen que estar como palabras en el nombre
// ("JUAN PEREZ" matchea "PEREZ JUAN", pero "JUAN" no matchea "JUANCITO").
function coincideNombre(nombre, patron) {
  const palabras = new Set(normU(nombre).split(' ').filter(Boolean));
  const buscadas = normU(patron).split(' ').filter(Boolean);
  return buscadas.length > 0 && buscadas.every((w) => palabras.has(w));
}
function normFecha(v) {
  if (v === null || v === undefined || v === '') return null;
  if (v instanceof Date) return v.toISOString().slice(0, 10);
  const s = String(v).trim();
  const iso = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (iso) return iso[1] + '-' + iso[2] + '-' + iso[3];
  const ar = s.match(/^(\d{2})\/(\d{2})\/(\d{4})/);
  if (ar) return ar[3] + '-' + ar[2] + '-' + ar[1];
  return null;
}
function hoyLocal() {
  let tz = 'UTC';
  try { tz = $('Entrada').first().json.config.zona_horaria || 'UTC'; } catch (e) {}
  return new Date().toLocaleDateString('en-CA', { timeZone: tz });
}
function diaSemana(fechaISO) { return new Date(fechaISO + 'T12:00:00Z').getUTCDay(); }

const items = $input.all();
const entrada = $('Entrada').first().json;
const A = entrada.config.asesores;
const nombreAsesor = entrada.nombre_asesor || null;

const excluido = (a) =>
  (A.excluir_ids || []).map(Number).includes(Number(a.advisorId)) ||
  (A.excluir_nombres || []).some((n) => coincideNombre(a.advisorName, n));

const todos = items.map((i) => i.json).filter((a) => a && a.advisorId && !excluido(a));
if (!todos.length) {
  return [{ json: { advisorId: null, advisorName: null, schedules: [], mensaje: 'No hay asesores disponibles para ese horario' } }];
}

if (nombreAsesor) {
  const match = todos.find((a) => coincideNombre(a.advisorName, nombreAsesor));
  if (match) return { json: { advisorId: match.advisorId, advisorName: match.advisorName, schedules: match.schedules } };
}

const selected = todos[Math.floor(Math.random() * todos.length)];
return { json: { advisorId: selected.advisorId, advisorName: selected.advisorName, schedules: selected.schedules } };

// get_user — datos del cliente/vehículo devueltos por Agenda Ford
const items = $input.all();
if (!items.length) throw new Error('No hay datos de entrada');

let raw = items[0].json;
let cliente = Array.isArray(raw) ? raw[0] : raw;
if (!cliente || typeof cliente !== 'object') throw new Error('Formato de entrada inválido');

const entrada = $('Entrada').first().json;
const S = entrada.config.servicios;

// Frecuencia de service por grupo de modelo (y año desde) — configurable en config.servicios.km_frecuencias
function getKmFrequency(groupR, modelYear) {
  const g = Number(groupR);
  const y = parseInt(modelYear) || 0;
  for (const r of S.km_frecuencias || []) {
    if (!(r.grupos || []).map(Number).includes(g)) continue;
    if (r.desde_anio && y < Number(r.desde_anio)) continue;
    return Number(r.km);
  }
  return Number(S.km_frecuencia_default);
}

// Un VIN tiene 17 caracteres; cualquier otra cosa es patente (vieja ABC123 o nueva AB123CD).
const ingresado = entrada.patente;
const esChasis = ingresado.length === 17;

return [{ json: {
  customerK:       cliente.customerK ?? null,
  model:           cliente.model || null,
  model_id:        cliente.groupR || null,
  modelYear:       cliente.modelYear ?? null,
  plate:           cliente.plate || null,
  chassi:          esChasis ? ingresado : (cliente.chassi || null),
  nationalId:      cliente.nationalId || null,
  firstname:       cliente.firstname || null,
  lastname:        cliente.lastname || null,
  email:           cliente.email || null,
  id_conversation: entrada.id_conversation,
  company:         Number(entrada.config.token_company) || null,
  km_frequency:    getKmFrequency(cliente.groupR, cliente.modelYear),
} }];

// Obtenemos todos los items del input
const items = $input.all();

if (!items.length) {
  throw new Error('No hay datos de entrada');
}

let root = items[0].json;

if (Array.isArray(root)) {
  if (!root.length) throw new Error('El array raíz está vacío');
  root = root[0];
}

if (!root || typeof root !== 'object') {
  throw new Error('Formato de entrada inválido');
}

const services = Array.isArray(root.response) ? root.response : [];
if (!services.length) {
  throw new Error('No se encontraron servicios en root.response');
}

// 🔥 Normaliza texto (sin tildes, minúscula)
function normalizeText(text) {
  return (text ?? "")
    .toString()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim();
}

const EXCLUIDOS = ($('Entrada').first().json.config.servicios.excluir_nombres || []).map((x) => normalizeText(x)).filter(Boolean);

const output = [];

for (const svc of services) {
  const serviceNameNorm = normalizeText(svc.serviceName);

  // ❌ Servicios excluidos (config.servicios.excluir_nombres)
  if (EXCLUIDOS.some((x) => serviceNameNorm.includes(x))) continue;

  const servicesByModelGroup = Array.isArray(svc.servicesByModelGroup)
    ? svc.servicesByModelGroup
    : [];

  let promo = null;
  for (const mg of servicesByModelGroup) {
    if (mg.promotionalActive) {
      promo = mg;
      break;
    }
  }

  const price = promo && typeof promo.promotionalPrice === 'number'
    ? promo.promotionalPrice
    : svc.servicePrice ?? null;

  const simplified = {
    serviceId: svc.serviceId,
    name: svc.serviceName,
    description: svc.name ?? null,
    price,
    normalPrice: svc.servicePrice ?? null,
    isPromo: !!(promo && promo.promotionalActive),
  };

  output.push({ json: simplified });
}

return output;

// Obtener input
const items = $input.all();

if (!items.length) {
  throw new Error('No hay datos de entrada');
}

// El input que mostraste es:
// [ { httpCode, message, response: [ { ...mantenimiento }, ... ] } ]
let root = items[0].json;

if (Array.isArray(root)) {
  if (!root.length) throw new Error('El array raíz está vacío');
  root = root[0];
}

if (!root || typeof root !== 'object') {
  throw new Error('Formato de entrada inválido');
}

const list = Array.isArray(root.response) ? root.response : [];
if (!list.length) {
  throw new Error('No se encontraron mantenimientos en root.response');
}

// Normalizamos fecha a "solo día"
function toDateOnly(value) {
  if (!value) return null;
  const d = new Date(value);
  if (isNaN(d.getTime())) return null;
  d.setHours(0, 0, 0, 0);
  return d;
}

const now = new Date();
now.setHours(0, 0, 0, 0);

const output = [];

for (const item of list) {
  const start = toDateOnly(item.modelStartDate);
  const end = toDateOnly(item.modelEndDate);

  if (!start || !end) {
    continue; // si no tiene fechas válidas, lo salteamos
  }

  // vigente si: start <= now <= end
  if (start <= now && now <= end) {
    output.push({
      json: {
        maintenanceCode: item.maintenanceCode,
        months: item.mounths ?? null, // el campo viene como "mounths"
        price: item.price ?? null,
      },
    });
  }
}

return output;

