// 🔥 Función para normalizar texto (quita tildes y pasa a minúscula)
function normalizeText(text) {
  return text
    ?.normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase();
}

const output = [];

for (const svc of services) {

  const serviceNameNormalized = normalizeText(svc.serviceName);

  // 🔎 FILTRO ROBUSTO POR "Diagnóstico"
  const clave = normalizeText($('Entrada').first().json.config.servicios.categoria_diagnostico || '');
  if (!clave || !serviceNameNormalized || !serviceNameNormalized.includes(clave)) {
    continue;
  }

  const servicesByModelGroup = Array.isArray(svc.servicesByModelGroup)
    ? svc.servicesByModelGroup
    : [];

  let promo = null;
  for (const mg of servicesByModelGroup) {
    if (mg.promotionalActive) {
