  };

  output.push({ json: simplified });
}

return output;

// Obtenemos los items de entrada
const items = $input.all();

if (!items.length) {
  throw new Error('No hay datos de entrada');
}

// El input viene como:
// [ { httpCode, message, response: [ { ...servicio }, ... ] } ]
let root = items[0].json;

if (Array.isArray(root)) {
  if (!root.length) {
    throw new Error('El array raíz está vacío');
  }
  root = root[0];
}

if (!root || typeof root !== 'object') {
  throw new Error('Formato de entrada inválido');
}

const list = Array.isArray(root.response) ? root.response : [];
if (!list.length) {
  throw new Error('No se encontraron servicios en root.response');
}

// Helper para normalizar fechas a "solo día"
function toDateOnly(value) {
  if (!value) return null;
  const d = new Date(value);
  if (isNaN(d.getTime())) return null;
  d.setHours(0, 0, 0, 0);
  return d;
}

// Helper para parsear montos (string o number)
function toNumber(value) {
  if (value === null || value === undefined) return 0;
  if (typeof value === 'number') return value;
  const s = String(value).replace(',', '.');
  const n = Number(s);
  return isNaN(n) ? 0 : n;
}

// Fecha actual (Argentina, pero solo día nos alcanza)
const now = new Date();
now.setHours(0, 0, 0, 0);

// Filtramos servicios vigentes hoy
const vigentes = list.filter(item => {
  const start = toDateOnly(item.modelStartDate);
  const end = toDateOnly(item.modelEndDate);
  if (!start || !end) return false;
  return start <= now && now <= end;
});

if (!vigentes.length) {
  throw new Error('No hay servicios vigentes para la fecha actual');
}

// Tomamos el primero vigente (en tu caso el de diciembre)
const svc = vigentes[0];

// Calculamos precio de ítems
const parts = Array.isArray(svc.revisionPartVOs) ? svc.revisionPartVOs : [];

let totalPartsPrice = 0;
const includedItems = parts.map(p => {
  const qty = toNumber(p.quantity);
  const price = toNumber(p.price);
  const subtotal = qty * price;
  totalPartsPrice += subtotal;

  return {
    description: p.longDescription || p.shortDescription || null,
    quantity: qty,
    unitPrice: price,
    subtotal,
  };
});

// Mano de obra
const labor = toNumber(svc.costLabor);

// Precio total = mano de obra + repuestos
const totalPrice = labor + totalPartsPrice;

// Ítems fijos que se suman a "qué incluye" (config.servicios.items_incluidos_extra)
for (const extra of ($('Entrada').first().json.config.servicios.items_incluidos_extra || [])) {
  includedItems.push({ description: extra.descripcion || extra.description || '', quantity: 1, unitPrice: 0, subtotal: 0 });
}
// Armamos salida simple
const result = {
  serviceId: svc.serviceId,
  serviceCode: svc.service,             // ej: SM01
  serviceDescription: svc.serviceDescription,
  monthService: svc.monthService,

  totalPrice,

  includes: includedItems,
};

return [
  {
    json: result,
  },
];

// get_detail_servicios — número de service y meses a partir del km declarado
const entrada = $('Entrada').first().json;
const S = entrada.config.servicios;
const dbData = $('Select rows from a table2').first().json;

// "45.000" o "45000" → 45000
const kmRaw = Number(String(entrada.km || '').replace(/[.\s]/g, '').replace(',', '.')) || 0;
const kmFrequency = Number(dbData.km_frequency) || Number(S.km_frecuencia_default);

// Sin km, se asume el primer service
const kmEfectivo = kmRaw > 0 ? kmRaw : kmFrequency;
const kmRedondeado = Math.max(kmFrequency, Math.round(kmEfectivo / kmFrequency) * kmFrequency);
const serviceNumber = Math.round(kmRedondeado / kmFrequency);
const mesesPorService = Number(S.meses_por_service);
const months = Math.max(mesesPorService, serviceNumber * mesesPorService);
const serviceId = Number(S.revision_service_id_base) + serviceNumber;

return [{ json: {
  km_original: kmRaw,
  km_redondeado: kmRedondeado,
  km_frequency: kmFrequency,
  service_number: serviceNumber,
  service_id: serviceId,
  months,
} }];

const fechaActual = $('Loop Over Items1').item.json.date;

function toMinutes(hhmm) {
  if (!hhmm) return null;
  const [h, m] = hhmm.split(':').map(Number);
  return h * 60 + m;
}

function toHHMM(mins) {
  const h = String(Math.floor(mins / 60)).padStart(2, '0');
  const m = String(mins % 60).padStart(2, '0');
  return `${h}:${m}`;
}

const data = $input.first().json.result;
const specialists = data?.technicalSpecialists || [];
const schedules = data?.schedules || [];
const resultado = [];

for (const esp of specialists) {
  const specialtyIds = (esp.specialties || []).map(s => s.id);

  const firstShift = esp.workSchedule?.firstShift;
  const secondShift = esp.workSchedule?.secondShift;

  // Si está totalmente no disponible o no tiene turnos configurados
  if (esp.availability?.totallyUnavailable || (!firstShift && !secondShift)) {
    resultado.push({
      json: {
        fechaActual,
        advisorId: esp.advisorId,
        advisorName: esp.advisorName,
        Huecos_Libres: [],
        specialtyIds
      }
    });
    continue;
  }

  // Obtenemos los bloqueos de indisponibilidad (soporta unavailableTimes y unavailablePeriods)
  const unavailableList = esp.availability?.unavailableTimes || esp.availability?.unavailablePeriods || [];

  const bloqueosIndisponibilidad = unavailableList
    .map(p => {
      const ini = toMinutes(p.startTime || p.start || p.entry);
      const fin = toMinutes(p.endTime || p.end || p.exit);
      return (ini !== null && fin !== null) ? [ini, fin] : null;
    })
    .filter(Boolean);

  // Obtenemos las citas ya agendadas
  const citasAgendadas = schedules
    .filter(s => s.productiveId === esp.advisorId || s.advisorId === esp.advisorId)
    .map(s => {
      const ini = toMinutes(s.startTime || s.start);
      const fin = toMinutes(s.endTime || s.end);
      return (ini !== null && fin !== null) ? [ini, fin] : null;
    })
    .filter(Boolean);

  // Unificamos y ordenamos todos los intervalos ocupados
  const ocupados = [...bloqueosIndisponibilidad, ...citasAgendadas].sort((a, b) => a[0] - b[0]);

  const turnosTrabajo = [];
  if (firstShift?.entry && firstShift?.exit) {
    turnosTrabajo.push([toMinutes(firstShift.entry), toMinutes(firstShift.exit)]);
  }
  if (secondShift?.entry && secondShift?.exit) {
    turnosTrabajo.push([toMinutes(secondShift.entry), toMinutes(secondShift.exit)]);
  }

  const huecos = [];
  for (const [inicioTurno, finTurno] of turnosTrabajo) {
    let cursor = inicioTurno;
    for (const [ini, fin] of ocupados) {
      if (fin <= cursor || ini >= finTurno) continue;
      if (ini > cursor) {
        huecos.push([cursor, Math.min(ini, finTurno)]);
      }
      cursor = Math.max(cursor, fin);
    }
    if (cursor < finTurno) {
      huecos.push([cursor, finTurno]);
    }
  }

  resultado.push({
    json: {
      fechaActual,
      advisorId: esp.advisorId,
        advisorName: esp.advisorName,
      Huecos_Libres: huecos.map(([ini, fin]) => `${toHHMM(ini)} - ${toHHMM(fin)}`),
      specialtyIds
    }
  });
}

return resultado;

const fechaActual = $('Loop Over Items5').item.json.date;

function toMinutes(hhmm) {
  if (!hhmm) return null;
  const [h, m] = hhmm.split(':').map(Number);
  return h * 60 + m;
}

function toHHMM(mins) {
  const h = String(Math.floor(mins / 60)).padStart(2, '0');
  const m = String(mins % 60).padStart(2, '0');
  return `${h}:${m}`;
}

function generarSlots(entry, exit, interval) {
  const inicio = toMinutes(entry);
  const fin = toMinutes(exit);
  if (inicio === null || fin === null) return [];

  const slots = [];
  for (let t = inicio; t < fin; t += interval) {
    slots.push(toHHMM(t));
  }
  return slots;
}

const inputData = $input.first()?.json?.result?.advisorDealerSchedule;
const interval = inputData?.interval || 20;
const advisors = inputData?.advisors || [];

const resultado = advisors.map(a => {
  // 1. Días libres / Ausencias activas hoy
  const daysOffActivos = (a.daysOffs || []).filter(off => {
    return fechaActual >= off.startDay && fechaActual <= off.endDay;
  });

  // Si tiene día libre completo, 0 disponibles
  if (daysOffActivos.some(off => off.allDay)) {
    return {
      json: {
        fechaActual,
        advisorId: a.advisorId,
        advisorName: a.advisorName,
        Slots_Libres: [],
        Cantidad_Slots_Libres: 0
      }
    };
  }

  // Sets de exclusión
  const slotsDaysOff = new Set();
  daysOffActivos.forEach(off => {
    if (off.offStartHour && off.offEndHour) {
      generarSlots(off.offStartHour, off.offEndHour, interval).forEach(s => slotsDaysOff.add(s));
    }
  });

  const reservadosSinCita = new Set((a.nonScheduled || []).map(s => s.passerbyHour));

  const asignados = new Set(
    (a.dealerSchedule || [])
      .filter(s => s.dateSchedule === fechaActual)
      .map(s => s.hourSchedule)
  );

  // 2. Grilla base de jornada
  const gridCompleto = [
    ...generarSlots(a.amEntrance, a.amExit, interval),
    ...generarSlots(a.pmEntrance, a.pmExit, interval)
  ];

  // 3. Filtrar turnos disponibles
  const slotsLibres = gridCompleto.filter(h => 
    !reservadosSinCita.has(h) && 
    !asignados.has(h) && 
    !slotsDaysOff.has(h)
  );

  return {
    json: {
      fechaActual,
      advisorId: a.advisorId,
      advisorName: a.advisorName,
      Slots_Libres: slotsLibres,
      Cantidad_Slots_Libres: slotsLibres.length
    }
  };
});

if (resultado.length === 0) {
  return [{
    json: {
      fechaActual,
      vacio: true,
      Slots_Libres: [],
      Cantidad_Slots_Libres: 0
    }
  }];
}

return resultado;

// Talleristas que califican (mantenimiento o taller móvil) y sus bloques libres en la grilla

function toMinutes(hhmm) {
  if (hhmm === null || hhmm === undefined) return null;
  const m = String(hhmm).match(/(\d{1,2}):(\d{2})/);
