const ESPERA_MAX = Number(T.espera_max_min) || 0;
const LIMITE_FIN = toMinutes(T.hora_limite_fin); // null = sin límite
const MAX_DIA = Number(T.max_por_dia) || 0;      // 0 = sin límite
const MAX_TOTAL = Number(T.max_total) || 0;      // 0 = sin límite
const TOLERANCIA = Number(T.tolerancia_hora_min) || 0;
const HABILITADOS = Array.isArray(T.dias_semana) && T.dias_semana.length ? T.dias_semana.map(Number) : [0, 1, 2, 3, 4, 5, 6];
const fechaHoy = hoyLocal();

