const asesorExcluido = (a) => !esMovil && (
  (CFG.asesores.excluir_ids || []).map(Number).includes(Number(a.advisorId)) ||
  (CFG.asesores.excluir_nombres || []).some((n) => coincideNombre(a.advisorName, n))
);

const items = $input.all().map((i) => i.json);
const diasAsesores = items.filter((i) => Array.isArray(i.detalleAsesores));
const mecanicos = items.filter((i) => Array.isArray(i.huecosLibres));

// Talleristas por fecha (ya filtrados por especialidad/exclusión en "Mecanicos libres")
const agenda = {};
for (const m of mecanicos) {
  const intervalos = m.huecosLibres
    .map((r) => r.split(/[-–—]/).map((s) => toMinutes(s.trim())))
    .filter((p) => p.length === 2 && p[0] !== null && p[1] !== null);
  (agenda[m.fecha] = agenda[m.fecha] || []).push({ id: m.mecanicoId ?? null, nombre: m.advisorName, intervalos });
}

const ofertas = [];
for (const dia of diasAsesores.slice().sort((a, b) => String(a.fecha).localeCompare(String(b.fecha)))) {
  const fecha = dia.fecha;
  if (!fecha) continue;
  if (T.excluir_hoy !== false && fecha === fechaHoy) continue;
  if (fecha < fechaHoy) continue;
  if (!HABILITADOS.includes(diaSemana(fecha))) continue;
  if (!fechaOk(fecha)) continue;
  const mecs = agenda[fecha] || [];
  if (!mecs.length) continue;

  // hora de recepción → asesores con esa hora libre (un solo turno por horario)
