        }
      }
      if (asignado) break;
    }
    if (!asignado) continue;

    const asesor = porHora.get(hora)[0];
    ofertas.push({
      fecha,
      fechaTexto: fechaTexto(fecha),
      horarioRecepcion: hora,
      asesorId: asesor.advisorId,
      asesorNombre: asesor.advisorName,
      mecanicoId: asignado.mec.id,
      mecanicoNombre: asignado.mec.nombre,
      huecoMecanico: toHHMM(asignado.inicio) + ' - ' + toHHMM(asignado.final),
