// Orden y límites
const referencia = fechaEsp && esFecha(fechaEsp) ? fechaEsp : fechaHoy;
const distancia = (f) => Math.abs((new Date(f + 'T12:00:00Z') - new Date(referencia + 'T12:00:00Z')) / 86400000);
ofertas.sort((a, b) =>
  (T.ordenar_por_cercania ? distancia(a.fecha) - distancia(b.fecha) : 0) ||
  a.fecha.localeCompare(b.fecha) ||
