// Reparto entre asesores: en cada día se ofrece primero el horario más temprano de
// cada asesor y recién después se repite asesor. Sin esto, con un máximo por día el
// asesor que tiene los horarios más tempranos se queda con todos los turnos.
const compararOfertas = (x, y) =>
  (T.ordenar_por_cercania ? distancia(x.fecha) - distancia(y.fecha) : 0) ||
  x.fecha.localeCompare(y.fecha) ||
