for (const fecha of diasEnOrden) {
  const porAsesor = new Map();
  for (const o of ofertasPorDia.get(fecha)) {
    const k = String(o.asesorId ?? o.asesorNombre);
    if (!porAsesor.has(k)) porAsesor.set(k, []);
    porAsesor.get(k).push(o);
  }
  const colas = [...porAsesor.values()];
  while (colas.some((c) => c.length)) {
    const ronda = colas.filter((c) => c.length).map((c) => c.shift());
    ronda.sort(compararOfertas);
    repartidas.push(...ronda);
  }
