const entrada = $('Entrada').first().json;
const CFG = entrada.config;
const T = CFG.turnos;
const MAPA_SERVICIOS = {
  5: 'Mantenimiento', 14: 'Taller Móvil', 111: 'Mantenimiento - Kit IOLM', 112: 'Reparación',
  113: 'Campañas De Servicio', 114: 'Diagnóstico', 115: 'Servicios Generales', 116: 'Accesorios',
  117: 'Lavado', 118: 'Colisión',
};

const DURACION = Number(T.duracion_min) || 60;
const APERTURA = toMinutes(T.hora_apertura) ?? 8 * 60;
const CIERRE = toMinutes(T.hora_cierre) ?? 17 * 60;

const excluido = (m) =>
  (CFG.mecanicos.excluir_ids || []).map(Number).includes(Number(m.advisorId)) ||
  (CFG.mecanicos.excluir_nombres || []).some((n) => coincideNombre(m.advisorName, n));

// Si la sucursal tiene talleristas permitidos, solo esos; si no, los de las especialidades configuradas
function califica(m) {
  const permitidos = CFG.mecanicos.permitidos || [];
  if (permitidos.length) return permitidos.some((n) => coincideNombre(m.advisorName, n));
  const ids = (m.specialtyIds || []).map(Number);
  return ids.some((id) => (CFG.mecanicos.especialidades_mantenimiento || []).map(Number).includes(id));
}

