  const rangos = (item.Huecos_Libres || [])
    .filter((r) => r && r.includes('-'))
    .map((r) => { const [a, b] = r.split('-').map((s) => s.trim()); return { ini: toMinutes(a), fin: toMinutes(b) }; })
    .filter((r) => r.ini !== null && r.fin !== null && r.fin > r.ini);

  // Grilla fija en punto (08:00, 09:00, ...): el bloque tiene que caer completo en un hueco
  const bloques = [];
  for (let ini = APERTURA; ini + DURACION <= CIERRE; ini += DURACION) {
    if (rangos.some((r) => r.ini <= ini && r.fin >= ini + DURACION)) {
      bloques.push(toHHMM(ini) + ' - ' + toHHMM(ini + DURACION));
    }
  }
  if (bloques.length) {
    resultado.push({ json: {
      fecha: item.fechaActual,
      mecanicoId: item.advisorId ?? null,
      advisorName: item.advisorName,
      servicios,
      specialtyIds: item.specialtyIds || [],
      huecosLibres: bloques,
    } });
  }
}
return resultado;

