}
function diaSemana(fechaISO) { return new Date(fechaISO + 'T12:00:00Z').getUTCDay(); }

const entrada = $('Entrada').first().json;
const CFG = entrada.config;
const T = CFG.turnos;
const esMovil = entrada.modalidad === 'movil';

const DIAS_SEMANA = { domingo: 0, lunes: 1, martes: 2, miercoles: 3, jueves: 4, viernes: 5, sabado: 6 };
const NOMBRES_DIAS = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
const NOMBRES_MESES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
const fechaTexto = (f) => { const d = new Date(f + 'T12:00:00Z'); return NOMBRES_DIAS[d.getUTCDay()] + ' ' + d.getUTCDate() + ' de ' + NOMBRES_MESES[d.getUTCMonth()]; };
const esFecha = (s) => /^\d{4}-\d{2}-\d{2}$/.test(String(s || '').trim());
const esHora = (s) => /^\d{1,2}:\d{2}$/.test(String(s || '').trim());

const DURACION = Number(T.duracion_min) || 60;
const ESPERA_MAX = Number(T.espera_max_min) || 0;
const LIMITE_FIN = toMinutes(T.hora_limite_fin); // null = sin límite
const MAX_DIA = Number(T.max_por_dia) || 0;      // 0 = sin límite
const MAX_TOTAL = Number(T.max_total) || 0;      // 0 = sin límite
const TOLERANCIA = Number(T.tolerancia_hora_min) || 0;
const HABILITADOS = Array.isArray(T.dias_semana) && T.dias_semana.length ? T.dias_semana.map(Number) : [0, 1, 2, 3, 4, 5, 6];
const fechaHoy = hoyLocal();

// Filtros pedidos por el cliente
let fechaEsp = String(entrada.fechaEspecifica || '').trim() || null;
let horaEsp = String(entrada.horaEspecifica || '').trim() || null;
if (horaEsp && esFecha(horaEsp) && !fechaEsp) { fechaEsp = horaEsp; horaEsp = null; }
if (horaEsp && !esHora(horaEsp)) horaEsp = null;
const fechaOk = (f) => {
  if (!fechaEsp) return true;
  if (esFecha(fechaEsp)) return f === fechaEsp;
  const dia = DIAS_SEMANA[normL(fechaEsp)];
  return dia === undefined ? true : diaSemana(f) === dia;
};
const horaOk = (h) => !horaEsp || Math.abs(toMinutes(h) - toMinutes(horaEsp)) <= TOLERANCIA;

// Asesores excluidos: no reciben turnos. En modalidad móvil la recepción la hace el asesor fijo del móvil.
const asesorExcluido = (a) => !esMovil && (
  (CFG.asesores.excluir_ids || []).map(Number).includes(Number(a.advisorId)) ||
  (CFG.asesores.excluir_nombres || []).some((n) => coincideNombre(a.advisorName, n))
);

const items = $input.all().map((i) => i.json);
const diasAsesores = items.filter((i) => Array.isArray(i.detalleAsesores));
const mecanicos = items.filter((i) => Array.isArray(i.huecosLibres));

// Talleristas por fecha (ya filtrados por especialidad/exclusión en "Mecanicos libres")
const agenda = {};
for (const m of mecanicos) {
  const intervalos = m.huecosLibres
    .map((r) => r.split(/[-–—]/).map((s) => toMinutes(s.trim())))
    .filter((p) => p.length === 2 && p[0] !== null && p[1] !== null);
  (agenda[m.fecha] = agenda[m.fecha] || []).push({ id: m.mecanicoId ?? null, nombre: m.advisorName, intervalos });
}

const ofertas = [];
for (const dia of diasAsesores.slice().sort((a, b) => String(a.fecha).localeCompare(String(b.fecha)))) {
  const fecha = dia.fecha;
  if (!fecha) continue;
  if (T.excluir_hoy !== false && fecha === fechaHoy) continue;
  if (fecha < fechaHoy) continue;
  if (!HABILITADOS.includes(diaSemana(fecha))) continue;
  if (!fechaOk(fecha)) continue;
  const mecs = agenda[fecha] || [];
  if (!mecs.length) continue;

  // hora de recepción → asesores con esa hora libre (un solo turno por horario)
  const porHora = new Map();
  for (const a of dia.detalleAsesores || []) {
