    if (!horaOk(hora)) continue;

    let asignado = null;
    for (const mec of mecs) {
      for (let i = 0; i < mec.intervalos.length && !asignado; i++) {
        const [ini, fin] = mec.intervalos[i];
        const inicio = Math.max(minRecepcion, ini);
        const final = inicio + DURACION;
        const espera = inicio - minRecepcion;
        if (espera <= ESPERA_MAX && final <= fin && (LIMITE_FIN === null || final <= LIMITE_FIN)) {
          asignado = { mec, inicio, final, espera };
          // descontar el bloque usado del tallerista
          const resto = [];
          if (inicio > ini) resto.push([ini, inicio]);
          if (fin > final) resto.push([final, fin]);
          mec.intervalos.splice(i, 1, ...resto);
        }
      }
      if (asignado) break;
    }
    if (!asignado) continue;

    const asesor = porHora.get(hora)[0];
    ofertas.push({
      fecha,
      fechaTexto: fechaTexto(fecha),
      horarioRecepcion: hora,
      asesorId: asesor.advisorId,
      asesorNombre: asesor.advisorName,
      mecanicoId: asignado.mec.id,
      mecanicoNombre: asignado.mec.nombre,
      huecoMecanico: toHHMM(asignado.inicio) + ' - ' + toHHMM(asignado.final),
      diferenciaEsperaMinutos: asignado.espera,
    });
  }
}

// Orden y límites
const referencia = fechaEsp && esFecha(fechaEsp) ? fechaEsp : fechaHoy;
const distancia = (f) => Math.abs((new Date(f + 'T12:00:00Z') - new Date(referencia + 'T12:00:00Z')) / 86400000);
ofertas.sort((a, b) =>
  (T.ordenar_por_cercania ? distancia(a.fecha) - distancia(b.fecha) : 0) ||
  a.fecha.localeCompare(b.fecha) ||
  toMinutes(a.horarioRecepcion) - toMinutes(b.horarioRecepcion));

// Reparto entre asesores: en cada día se ofrece primero el horario más temprano de
// cada asesor y recién después se repite asesor. Sin esto, con un máximo por día el
// asesor que tiene los horarios más tempranos se queda con todos los turnos.
const compararOfertas = (x, y) =>
  (T.ordenar_por_cercania ? distancia(x.fecha) - distancia(y.fecha) : 0) ||
  x.fecha.localeCompare(y.fecha) ||
  toMinutes(x.horarioRecepcion) - toMinutes(y.horarioRecepcion);
const diasEnOrden = [];
const ofertasPorDia = new Map();
for (const o of ofertas) {
  if (!ofertasPorDia.has(o.fecha)) { ofertasPorDia.set(o.fecha, []); diasEnOrden.push(o.fecha); }
  ofertasPorDia.get(o.fecha).push(o);
}
const repartidas = [];
for (const fecha of diasEnOrden) {
  const porAsesor = new Map();
  for (const o of ofertasPorDia.get(fecha)) {
    const k = String(o.asesorId ?? o.asesorNombre);
    if (!porAsesor.has(k)) porAsesor.set(k, []);
    porAsesor.get(k).push(o);
  }
  const colas = [...porAsesor.values()];
  while (colas.some((c) => c.length)) {
    const ronda = colas.filter((c) => c.length).map((c) => c.shift());
    ronda.sort(compararOfertas);
    repartidas.push(...ronda);
  }
}

const porFecha = {};
const horasUsadas = new Set();
const finales = [];
for (const o of repartidas) {
  if (MAX_TOTAL && finales.length >= MAX_TOTAL) break;
  if (MAX_DIA && (porFecha[o.fecha] || 0) >= MAX_DIA) continue;
  if (T.sin_horarios_repetidos && horasUsadas.has(o.horarioRecepcion)) continue;
  finales.push({ json: o });
  porFecha[o.fecha] = (porFecha[o.fecha] || 0) + 1;
  horasUsadas.add(o.horarioRecepcion);
}

// Lo que se muestra va en orden de fecha y hora.
finales.sort((x, y) => compararOfertas(x.json, y.json));

if (!finales.length) {
  return [{ json: { turnosEncontrados: 0, mensaje: 'No hay turnos disponibles para los filtros solicitados' } }];
}
return finales;

