const DURACION = Number(T.duracion_min) || 60;
const ESPERA_MAX = Number(T.espera_max_min) || 0;
const LIMITE_FIN = toMinutes(T.hora_limite_fin);
const IDS_MANT = (CFG.mecanicos.especialidades_mantenimiento || []).map(Number);

const excluido = (esp) =>
  (CFG.mecanicos.excluir_ids || []).map(Number).includes(Number(esp.advisorId)) ||
  (CFG.mecanicos.excluir_nombres || []).some((n) => coincideNombre(esp.advisorName, n));

const inputItem = $input.all()[0]?.json;
const data = inputItem?.result || inputItem;
const specialists = data?.technicalSpecialists || [];
const schedules = data?.schedules || [];

const candidatos = [];
for (const esp of specialists) {
  const ids = (esp.specialties || []).map((s) => Number(s.id));
  const nombres = (esp.specialties || []).map((s) => s.name);
  if (excluido(esp)) continue;

  // Talleristas permitidos de la sucursal, o los de las especialidades configuradas
  const permitidos = CFG.mecanicos.permitidos || [];
  const porId = ids.find((id) => IDS_MANT.includes(id));
  if (permitidos.length ? !permitidos.some((n) => coincideNombre(esp.advisorName, n)) : porId === undefined) continue;
  const especialidadTurno = porId ?? IDS_MANT[0] ?? ids[0] ?? null;

  const first = esp.workSchedule?.firstShift;
  const second = esp.workSchedule?.secondShift;
  if (esp.availability?.totallyUnavailable || (!first && !second)) continue;

  const bloqueos = [
    ...(esp.availability?.unavailableTimes || []),
    ...(esp.availability?.unavailablePeriods || []),
  ].map((p) => [toMinutes(p.startTime || p.start || p.entry), toMinutes(p.endTime || p.end || p.exit)])
   .filter((p) => p[0] !== null && p[1] !== null);
  // En schedules, advisorId es el asesor de servicio: el tallerista es productiveId
  const citas = schedules.filter((s) => s.productiveId === esp.advisorId)
    .map((s) => [toMinutes(s.startTime || s.start), toMinutes(s.endTime || s.end)])
    .filter((p) => p[0] !== null && p[1] !== null);
  const ocupados = [...bloqueos, ...citas].sort((a, b) => a[0] - b[0]);

  const turnos = [];
  if (first?.entry && first?.exit) turnos.push([toMinutes(first.entry), toMinutes(first.exit)]);
  if (second?.entry && second?.exit) turnos.push([toMinutes(second.entry), toMinutes(second.exit)]);

  const huecos = [];
  for (const [ini, fin] of turnos) {
    let cursor = ini;
    for (const [a, b] of ocupados) {
      if (b <= cursor || a >= fin) continue;
      if (a > cursor) huecos.push([cursor, Math.min(a, fin)]);
      cursor = Math.max(cursor, b);
    }
    if (cursor < fin) huecos.push([cursor, fin]);
  }

  for (const [ini, fin] of huecos) {
    const inicio = Math.max(minRecepcion, ini);
    const final = inicio + DURACION;
    const espera = inicio - minRecepcion;
    if (espera <= ESPERA_MAX && final <= fin && (LIMITE_FIN === null || final <= LIMITE_FIN)) {
      const preferido = (mecanicoPedido && Number(esp.advisorId) === mecanicoPedido) ||
        (mecanicoPedidoNombre && coincideNombre(esp.advisorName, mecanicoPedidoNombre));
      candidatos.push({
        fecha,
        horarioRecepcion: horaRecepcion,
        asesorNombre: nombreAsesor,
        mecanicoId: esp.advisorId,
        mecanicoNombre: esp.advisorName,
        servicios: nombres,
        specialtyIds: ids,
        especialidadTurno,
        productiveAttendanceHour: toHHMM(inicio),
        productiveAttendanceEndHour: toHHMM(final),
        huecoMecanico: toHHMM(inicio) + ' - ' + toHHMM(final),
        diferenciaEsperaMinutos: espera,
        preferido: !!preferido,
      });
      break;
    }
  }
}

if (!candidatos.length) {
  return [{ json: { fecha, horarioRecepcion: horaRecepcion, encontrado: false, esMovil,
    mensaje: 'No hay talleristas disponibles en ese horario' } }];
}

// Primero el tallerista del turno ofrecido (si sigue libre), después el de menor espera
candidatos.sort((a, b) => (b.preferido - a.preferido) || (a.diferenciaEsperaMinutos - b.diferenciaEsperaMinutos));
const mejor = candidatos[0];

// Sucursal con asesor fijo (modalidad móvil): la recepción la hace siempre ese asesor
let advisorId = null;
if (esMovil) {
  let asesores39 = [];
  try { asesores39 = $('Code39').all().map((i) => i.json); } catch (e) {}
  const movil = CFG.movil.asesor_nombre ? asesores39.find((a) => coincideNombre(a.advisorName, CFG.movil.asesor_nombre)) : null;
  advisorId = movil ? Number(movil.advisorId) : (Number(CFG.movil.asesor_id) || null);
}

return [{ json: { ...mejor, encontrado: true, esMovil, advisorId } }];

// ==========================================================
// Code31 - Cálculo de Slots Libres por Asesor (Fecha Puntual / Loop)
// ==========================================================

function toMinutes(hhmm) {
  if (!hhmm) return null;
  const match = String(hhmm).match(/(\d{1,2}):(\d{2})/);
  if (!match) return null;
  return parseInt(match[1], 10) * 60 + parseInt(match[2], 10);
}

function toHHMM(mins) {
  const h = String(Math.floor(mins / 60)).padStart(2, '0');
  const m = String(mins % 60).padStart(2, '0');
  return `${h}:${m}`;
}

function generarSlots(entry, exit, interval) {
  const inicio = toMinutes(entry);
  const fin = toMinutes(exit);
  if (inicio === null || fin === null) return [];

  const slots = [];
  for (let t = inicio; t < fin; t += interval) {
    slots.push(toHHMM(t));
  }
  return slots;
}

// Obtener fecha actual desde el Loop o fallback
let fechaActual = null;
try {
  fechaActual = $('Loop Over Items5').item?.json?.date;
} catch (e) {}

if (!fechaActual) {
  try {
    fechaActual = $('Select rows from a table4').first()?.json?.selected_date;
  } catch (e) {}
}

const inputData = $input.first()?.json?.result?.advisorDealerSchedule;
const interval = inputData?.interval || 20;
const advisors = inputData?.advisors || [];

// Fallback de fecha usando el primer dealerSchedule si no vino por variable
if (!fechaActual && advisors.length > 0) {
  fechaActual = advisors[0]?.dealerSchedule?.[0]?.dateSchedule || new Date().toISOString().split('T')[0];
}

const resultado = advisors.map(a => {
  // 1. Filtrar días libres / ausencias vigentes en esta fecha
  const daysOffActivos = (a.daysOffs || []).filter(off => {
    return fechaActual >= off.startDay && fechaActual <= off.endDay;
  });

  // Si tiene el día completo libre, retorna 0 disponibles
  if (daysOffActivos.some(off => off.allDay)) {
    return {
      json: {
        fechaActual,
        advisorId: a.advisorId,
        advisorName: a.advisorName,
        Slots_Libres: [],
        Cantidad_Slots_Libres: 0
      }
    };
  }

  // 2. Slots bloqueados por franja horaria de daysOffs
  const slotsDaysOff = new Set();
  daysOffActivos.forEach(off => {
    if (off.offStartHour && off.offEndHour) {
      generarSlots(off.offStartHour, off.offEndHour, interval).forEach(s => slotsDaysOff.add(s));
    }
  });

  // 3. Bloqueados sin cita (passerby)
  const reservadosSinCita = new Set((a.nonScheduled || []).map(s => s.passerbyHour).filter(Boolean));

  // 4. Turnos asignados específicamente en esta fecha
  const asignados = new Set(
    (a.dealerSchedule || [])
      .filter(s => s.dateSchedule === fechaActual && s.hourSchedule)
      .map(s => s.hourSchedule)
  );

  // 5. Grilla completa de trabajo del asesor
  const gridCompleto = [
    ...generarSlots(a.amEntrance, a.amExit, interval),
    ...generarSlots(a.pmEntrance, a.pmExit, interval)
  ];

  // 6. Exclusión de ocupados
  const slotsLibres = gridCompleto.filter(h => 
    !reservadosSinCita.has(h) && 
    !asignados.has(h) && 
    !slotsDaysOff.has(h)
  );

  return {
    json: {
      fechaActual,
      advisorId: a.advisorId,
      advisorName: a.advisorName,
      Slots_Libres: slotsLibres,
      Cantidad_Slots_Libres: slotsLibres.length
    }
  };
});

if (resultado.length === 0) {
  return [{
    json: {
      fechaActual,
      vacio: true,
      Slots_Libres: [],
      Cantidad_Slots_Libres: 0
    }
  }];
}

return resultado;

// ==========================================================
// Bloques Ocupados - Fecha Puntual
// ==========================================================

function toMinutes(hhmm) {
  if (!hhmm) return null;
  const [h, m] = hhmm.split(':').map(Number);
  return h * 60 + m;
}

function toHHMM(mins) {
  const h = String(Math.floor(mins / 60)).padStart(2, '0');
  const m = String(mins % 60).padStart(2, '0');
  return `${h}:${m}`;
}

function generarSlots(entry, exit, interval) {
  const inicio = toMinutes(entry);
  const fin = toMinutes(exit);
  if (inicio === null || fin === null) return [];

  const slots = [];
  for (let t = inicio; t < fin; t += interval) {
    slots.push(toHHMM(t));
  }
  return slots;
}

// Obtener fecha puntual (desde nodo previo o fallback a la fecha del dealerSchedule)
let fechaActual = null;
try {
  fechaActual = $('Loop Over Items5').item.json.date;
} catch (e) {
  try {
    fechaActual = $('Select rows from a table4').first()?.json?.selected_date;
  } catch (err) {
    fechaActual = null;
  }
}

const inputData = $input.first()?.json?.result?.advisorDealerSchedule;
const interval = inputData?.interval || 20;
const advisors = inputData?.advisors || [];

const resultado = advisors.map(a => {
  const gridCompleto = [
    ...generarSlots(a.amEntrance, a.amExit, interval),
    ...generarSlots(a.pmEntrance, a.pmExit, interval)
  ];

  const slotsBloqueadosSet = new Set();

  // 1. Filtrar daysOffs vigentes para la fecha actual
  const daysOffActivos = (a.daysOffs || []).filter(off => {
    return fechaActual >= off.startDay && fechaActual <= off.endDay;
  });

  const tieneDiaLibreCompleto = daysOffActivos.some(off => off.allDay);
  if (tieneDiaLibreCompleto) {
    gridCompleto.forEach(s => slotsBloqueadosSet.add(s));
  } else {
    // Franjas horarias bloqueadas por descanso
    daysOffActivos.forEach(off => {
      if (off.offStartHour && off.offEndHour) {
        const slotsOff = generarSlots(off.offStartHour, off.offEndHour, interval);
        slotsOff.forEach(s => slotsBloqueadosSet.add(s));
      }
    });
  }

  // 2. Bloqueos por nonScheduled (sin cita / transeúntes)
  (a.nonScheduled || []).forEach(s => {
    if (s.passerbyHour) slotsBloqueadosSet.add(s.passerbyHour);
  });

  // 3. Bloqueos por turnos ya agendados para este día puntual
  (a.dealerSchedule || []).forEach(s => {
    if (s.dateSchedule === fechaActual && s.hourSchedule) {
      slotsBloqueadosSet.add(s.hourSchedule);
    }
  });

  // Ordenar cronológicamente
  const slotsOcupados = Array.from(slotsBloqueadosSet).sort((x, y) => toMinutes(x) - toMinutes(y));

  return {
    json: {
      fechaActual,
      advisorId: a.advisorId,
      advisorName: a.advisorName,
      Slots_Bloqueados: slotsOcupados,
      Cantidad_Slots_Bloqueados: slotsOcupados.length
    }
  };
});

if (resultado.length === 0) {
  return [{
    json: {
      fechaActual,
      vacio: true,
      Slots_Bloqueados: [],
      Cantidad_Slots_Bloqueados: 0
    }
  }];
}

return resultado;

