const entrada = $('Entrada').first().json;
const A = entrada.config.asesores;
const code13 = $('Code13').first().json;
const asesores = $('Code39').all().map((i) => i.json).filter((a) => a && a.advisorId);

const hora = code13.horarioRecepcion;
const mecanicoOk = code13.encontrado !== false && code13.mecanicoId != null;

let advisorId = null;
let advisorName = null;
let advisorLibre = false;
let motivoAsesor = 'advisor_not_found';

if (code13.esMovil) {
  // Móvil: atiende el tallerista del móvil; el asesor es el fijo del móvil
  advisorId = Number(code13.advisorId) || null;
  advisorLibre = !!advisorId;
} else {
  const excluido = (a) =>
    (A.excluir_ids || []).map(Number).includes(Number(a.advisorId)) ||
    (A.excluir_nombres || []).some((n) => coincideNombre(a.advisorName, n));
  const idPedido = Number(entrada.contexto?.asesor_id) || null;
  const nombrePedido = entrada.nombre_asesor || code13.asesorNombre || '';

  let info = null;
  if (idPedido) info = asesores.find((a) => Number(a.advisorId) === idPedido) || null;
  if (!info && nombrePedido) info = asesores.find((a) => normU(a.advisorName) === normU(nombrePedido)) || null;
  if (!info && nombrePedido) info = asesores.find((a) => coincideNombre(a.advisorName, nombrePedido) && coincideNombre(nombrePedido, a.advisorName)) || null;

  if (info && excluido(info)) {
    motivoAsesor = 'advisor_excluded';
    info = null;
  }
  if (info) {
    advisorId = Number(info.advisorId);
    advisorName = info.advisorName;
    advisorLibre = (info.Slots_Libres || []).includes(hora);
    motivoAsesor = advisorLibre ? null : 'advisor_slot_unavailable';
  }
}

const ok = !!(advisorId && advisorLibre && mecanicoOk);
return [{ json: {
