  }
}];

// ==========================================================
// Pedido — lee el body del webhook. No tiene ningún dato de concesionario:
// la configuración se busca en ford_agenda_config con client_id.
// ==========================================================
const esObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const str = (v) => (v === undefined || v === null ? '' : String(v).trim());
const raw = $input.first().json;
const src = esObj(raw.body) ? raw.body : raw;
const contexto = esObj(src.contexto) ? src.contexto : {};
const pick = (...keys) => {
  for (const k of keys) {
    const v = src[k] ?? contexto[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return v;
  }
  return '';
};

const out = {
  action: str(src.action),
  client_id: Number(pick('client_id')) || null,
  branch_id: Number(pick('branch_id')) || null,
  sucursal: str(pick('sucursal')),
  modalidad: str(pick('modalidad')).toLowerCase(),
  id_conversation: str(pick('id_conversation')),
  patente: str(pick('patente')).toUpperCase(),
  chassis: str(pick('chassis', 'chasis')).toUpperCase(),
  date: str(pick('date')),
  hour: str(pick('hour')),
  fechaElegida: str(pick('fechaElegida')),
  fechaEspecifica: str(pick('fechaEspecifica')),
  horaEspecifica: str(pick('horaEspecifica')),
  km: str(pick('km')),
  months: str(pick('months')),
  resumen: str(pick('resumen')),
  nombre_asesor: str(pick('nombre_asesor')),
  customerK: str(pick('customerK')),
  telefono: str(pick('telefono')),
  // Booleano de Agenda Ford: ai-agent lo manda en TODO pedido y Entrada lo exige.
  agenda_ford: src.agenda_ford === true || str(src.agenda_ford).toLowerCase() === 'true',
  contexto,
};

if (!out.action) throw new Error('Falta "action" en el pedido');
if (!out.client_id) throw new Error('Falta "client_id" en el pedido');
if (!out.id_conversation && out.action !== 'alerta') throw new Error('Falta "id_conversation" en el pedido');

return [{ json: out }];

