const objeto = (v) => { const x = parse(v); return x && typeof x === 'object' && !Array.isArray(x) ? x : {}; };
const bool = (v) => v === true || v === 1 || v === '1';
const sinBarraFinal = (u) => { let x = String(u || ''); while (x.endsWith('/')) x = x.slice(0, -1); return x; };
const num = (v) => (v === null || v === undefined || v === '' ? null : Number(v));
const error = (codigo, mensaje) => [{ json: { ok: false, success: false, error: codigo, mensaje } }];

// Booleano de Agenda Ford: ai-agent lo manda en TODO pedido. Sin él en true no se
// responde nada: este workflow solo atiende el flujo de Agenda Ford.
if (pedido.agenda_ford !== true) return error('agenda_ford_requerido', 'El pedido no viene del flujo de Agenda Ford (falta agenda_ford=true)');

const cfg = $('Leer config Ford').first().json || {};
if (!cfg.id) return error('config_not_found', 'No hay configuración de Agenda Ford activa para el cliente ' + pedido.client_id);

// Sucursal: por branch_id de Redoo, o por dealer_code (+ modo si comparten dealer)
const sucursales = $('Leer sucursales Ford').all().map((i) => i.json).filter((x) => x && x.id);
const modoPedido = ['movil', 'mobile'].includes(pedido.modalidad) ? 'mobile' : 'workshop';
let suc = null;
if (pedido.branch_id) suc = sucursales.find((x) => Number(x.branch_id) === pedido.branch_id) || null;
if (!suc && pedido.sucursal) {
  const mismas = sucursales.filter((x) => String(x.dealer_code) === pedido.sucursal);
  suc = mismas.find((x) => x.mode === modoPedido) || mismas[0] || null;
}
if (!suc && pedido.action !== 'alerta') {
  return error('branch_not_found', 'La sucursal no está configurada en Agenda Ford (branch_id ' + pedido.branch_id + ', dealer ' + pedido.sucursal + ')');
}
const esMovil = suc?.mode === 'mobile';

// Exclusiones de todas las sucursales + las de esta sucursal
const exclusiones = $('Leer exclusiones Ford').all().map((i) => i.json)
  .filter((x) => x && x.id && (!x.branch_id || (suc && Number(x.branch_id) === Number(suc.branch_id))));
const nombres = (kind) => exclusiones.filter((x) => x.kind === kind && x.name).map((x) => x.name);
const ids = (kind) => exclusiones.filter((x) => x.kind === kind && x.ford_id).map((x) => Number(x.ford_id));

// Reglas de turnos: las del concesionario, pisadas por las de la sucursal (rule_overrides)
const r = { ...cfg, ...objeto(suc?.rule_overrides) };
const especialidadesSucursal = lista(suc?.specialty_ids);

// Frecuencia de service por grupo de modelo y año — valores de Ford para todos los
// concesionarios. Se usa solo si la config del cliente no trae reglas propias
// (ford_agenda_configs.km_frequencies); con reglas propias manda la config.
// La primera regla que coincide gana; lo que no figura usa km_frecuencia_default.
const KM_FRECUENCIAS_FORD = [
  { grupos: [9], desde_anio: 2024, km: 16000 }, // Ranger anterior, modelo 2024 o más
  { grupos: [9], km: 10000 }, // Ranger anterior
  { grupos: [14], desde_anio: 2021, km: 16000 }, // Transit 2021 o más
  { grupos: [19], km: 10000 }, // Territory
  { grupos: [20, 24, 26, 27, 28, 30], km: 16000 }, // Bronco Sport, Ranger, Mach-E, Ranger Raptor, Bronco, Everest
];

const config = {
  api: {
    base_url: sinBarraFinal(cfg.api_base_url),
    pais: cfg.country_code,
    division: num(cfg.division_code),
    portal_origin: sinBarraFinal(cfg.portal_origin),
  },
  zona_horaria: cfg.timezone,
  token_company: num(cfg.token_company),
  usuario_ford: cfg.ford_user,
  asesores: { excluir_nombres: nombres('advisor'), excluir_ids: ids('advisor') },
  mecanicos: {
    especialidades_mantenimiento: especialidadesSucursal.length ? especialidadesSucursal : lista(cfg.maintenance_specialty_ids),
    permitidos: lista(suc?.allowed_mechanics),
    excluir_nombres: nombres('mechanic'),
    excluir_ids: ids('mechanic'),
  },
  // Asesor de recepción fijo de la sucursal (modalidad móvil)
  movil: {
    asesor_nombre: suc?.fixed_advisor_name || '',
    asesor_id: num(suc?.fixed_advisor_id),
  },
  turnos: {
    dias_adelante: num(r.days_ahead),
    excluir_hoy: bool(r.exclude_today),
    dias_semana: lista(r.weekdays),
    duracion_min: num(r.service_duration_min),
    espera_max_min: num(r.max_wait_min),
    hora_apertura: r.open_time,
    hora_cierre: r.close_time,
    hora_limite_fin: r.end_limit_time || null,
    max_por_dia: num(r.max_per_day),
    max_total: num(r.max_total),
    tolerancia_hora_min: num(r.time_tolerance_min),
    ordenar_por_cercania: bool(r.sort_by_proximity),
    sin_horarios_repetidos: bool(r.no_repeated_times),
  },
  servicios: {
    excluir_nombres: lista(cfg.excluded_services),
    km_frecuencia_default: num(cfg.default_km_frequency),
    km_frecuencias: lista(cfg.km_frequencies).length ? lista(cfg.km_frequencies) : KM_FRECUENCIAS_FORD,
    revision_service_id_base: num(cfg.revision_service_id_base),
    meses_por_service: num(cfg.months_per_service),
    items_incluidos_extra: lista(cfg.extra_included_items),
    budget_group: num(cfg.budget_group),
    categoria_reparacion: cfg.repair_keyword || '',
    categoria_diagnostico: cfg.diagnosis_keyword || '',
  },
  reserva: {
    send_email: bool(cfg.send_email),
    schedule_source: cfg.schedule_source,
    schedule_type: cfg.schedule_type,
    template_cliente: cfg.customer_remark_template || '',
    template_concesionario: cfg.dealer_remark_template || '',
  },
  consultas: {
    meses_adelante: num(cfg.lookup_months_ahead),
    tipos_reserva: lista(cfg.reservation_types).length ? lista(cfg.reservation_types) : ['NORMAL'],
  },
  alerta: {
    activa: bool(cfg.alert_enabled),
    emails: lista(cfg.alert_emails),
    asunto: cfg.alert_subject || '',
    mensaje: cfg.alert_message || '',
  },
};

return [{ json: {
  ...pedido,
  ok: true,
  sucursal: suc ? String(suc.dealer_code) : '',
  sucursal_nombre: suc?.nombre || '',
  modalidad: esMovil ? 'movil' : 'taller',
  gralPico: esMovil ? 'si' : 'no',
  config,
} }];

// Datos de la conversación que ai-agent manda en "contexto" y se guardan en agenda_ford
// antes de ejecutar la acción (reemplaza a saveSucursal / SelectedDate&Hour / addService).
const e = $('Entrada').first().json;
const c = e.contexto || {};
const row = { id_conversation: e.id_conversation };
const set = (col, v) => {
  if (v !== undefined && v !== null && String(v).trim() !== '') row[col] = v;
};
set('sucursal', e.sucursal);
set('selected_date', c.selected_date);
set('selected_hour', c.selected_hour);
set('service_id', c.service_id);
set('advisorId', c.advisor_id);
set('months', c.months);
if (Array.isArray(c.additionals_id)) {
  row.additionals_id = JSON.stringify(c.additionals_id.map(Number).filter(Number.isFinite));
}
return [{ json: row }];

// Arma el mail de alerta con la config del concesionario.
// Variables disponibles en asunto/mensaje: {{accion}} {{error}} {{sucursal}} {{patente}} {{conversacion}}
const e = $('Entrada').first().json;
const a = e.config.alerta || {};
const input = $input.first().json || {};
const c = e.contexto || {};
const vars = {
  accion: input.accion || c.accion_fallida || e.action,
  error: input.detalle || input.error || c.error || '',
  sucursal: e.sucursal,
  patente: e.patente,
  conversacion: e.id_conversation,
};
const fill = (t) => String(t || '').replace(/\{\{\s*(\w+)\s*\}\}/g, (_, k) => (vars[k] ?? ''));
const emails = (a.emails || []).filter(Boolean);
return [{ json: {
  activa: a.activa !== false && emails.length > 0,
  emails: emails.join(','),
  asunto: fill(a.asunto),
  mensaje: fill(a.mensaje),
} }];

return [{ json: {
  success: false,
  error: 'missing_context',
  mensaje: 'No hay datos guardados para esta conversación. Enviá la sucursal en "contexto".'
} }];

const err = $input.first().json.error;
return [{ json: {
  success: false,
  error: 'ford_contact_search_failed',
  accion: 'get_user',
  detalle: String(err?.message || err?.description || err || 'Error consultando el cliente en Agenda Ford'),
} }];

const ford = $input.first().json;
const res = $('Resolver Asesor Turno').first().json;
const c13 = $('Code13').first().json;
return [{ json: {
  success: true,
  fecha: c13.fecha,
  hora: c13.horarioRecepcion,
  asesor_id: res.advisorId,
  asesor_nombre: res.advisorName,
  mecanico_id: c13.mecanicoId,
  mecanico_nombre: c13.mecanicoNombre,
  respuesta_ford: ford,
} }];

const err = $input.first().json.error;
return [{ json: {
  success: false,
  error: 'ford_create_failed',
  accion: 'create_turno',
  detalle: String(err?.message || err?.description || err || 'Agenda Ford rechazó la reserva'),
} }];
